/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsrotaWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'ROTADESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &rotaDescricao1.FromString(&GridStateDynamicFilter.Value) If not &rotaDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&rotaDescricao1) EndIf Case &DynamicFiltersSelector1 = !'ROTASTATUS' &rotaStatus1.FromString(&GridStateDynamicFilter.Value) If not &rotaStatus1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Situação" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &rotaStatus1.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &rotaStatus1.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'ROTADESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &rotaDescricao2.FromString(&GridStateDynamicFilter.Value) If not &rotaDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&rotaDescricao2) EndIf Case &DynamicFiltersSelector2 = !'ROTASTATUS' &rotaStatus2.FromString(&GridStateDynamicFilter.Value) If not &rotaStatus2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Situação" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &rotaStatus2.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &rotaStatus2.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'ROTADESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &rotaDescricao3.FromString(&GridStateDynamicFilter.Value) If not &rotaDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&rotaDescricao3) EndIf Case &DynamicFiltersSelector3 = !'ROTASTATUS' &rotaStatus3.FromString(&GridStateDynamicFilter.Value) If not &rotaStatus3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = "Situação" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' do Case Case &rotaStatus3.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Ativo"
Case &rotaStatus3.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = "Inativo"
EndCase EndIf EndCase EndIf EndIf EndIf If not (&TFrotaCodigo.IsEmpty() AND &TFrotaCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFrotaCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFrotaCodigo_To EndIf If not (&TFrotaDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFrotaDescricao_Sel) Else If not (&TFrotaDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFrotaDescricao) EndIf EndIf If not (&TFrotaStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Situação") &i = 1 For &TFrotaStatus_Sel in &TFrotaStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFrotaStatus_Sel.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Ativo"
Case &TFrotaStatus_Sel.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Inativo"
EndCase &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsrotaWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsrotaWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsrota order rotaDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (rotaDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order rotaCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (rotaCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order rotaStatus when &OrderedBy = 3 AND &OrderedDsc = False order (rotaStatus) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsrotaWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &rotaDescricao1, &rotaStatus1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2 , &DynamicFiltersOperator2, &rotaDescricao2, &rotaStatus2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &rotaDescricao3, &rotaStatus3, &TFrotaCodigo, &TFrotaCodigo_To, &TFrotaDescricao, &TFrotaDescricao_Sel , &TFrotaStatus_Sels) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'rotaCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = rotaCodigo Case &ColumnsSelector_Column.ColumnName = !'rotaDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(rotaDescricao) Case &ColumnsSelector_Column.ColumnName = !'rotaStatus' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case rotaStatus.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Ativo"
Case rotaStatus.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Inativo"
EndCase EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsrotaWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"rotaCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"rotaDescricao", '', !'Descrição', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"rotaStatus", '', !'Situação', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsrotaWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsrotaWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsrotaWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsrotaWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFROTACODIGO" &TFrotaCodigo.FromString(&GridStateFilterValue.Value) &TFrotaCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFROTADESCRICAO" &TFrotaDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFROTADESCRICAO_SEL" &TFrotaDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFROTASTATUS_SEL" &TFrotaStatus_SelsJson = &GridStateFilterValue.Value &TFrotaStatus_Sels.FromJson(&TFrotaStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
